#pragma once

#include <stddef.h>
#include <stdint.h>

namespace fortis::security {

// Data tables generated by scripts/generate_redaction_tables.py into
// src/security/redaction_tables.cpp. See diagnostic_redaction.h for their use.
struct RedactionRange {
  uint32_t first;
  uint32_t last;
};

struct RedactionConfusable {
  uint32_t code_point;
  char ascii;
};

// One code point whose full compatibility decomposition (NFKD) differs from
// itself; its NFKD code points are kNfkdPool[offset, offset + length).
// Hangul syllables are decomposed arithmetically and are not listed.
struct NfkdMapping {
  uint32_t code_point;
  uint16_t offset;
  uint8_t length;
};

// Canonical primary composite of a (starter, following) pair.
struct CompositionPair {
  uint32_t first;
  uint32_t second;
  uint32_t composite;
};

extern const char kRedactionUnicodeVersion[];
extern const char kRedactionPlaceholder[];
extern const char* const kBip39English[2048];
extern const RedactionRange kRedactionInvisible[];
extern const size_t kRedactionInvisibleCount;
extern const RedactionConfusable kRedactionConfusables[];
extern const size_t kRedactionConfusableCount;
// A non-starter's canonical combining class, as a rank: ranks preserve the
// order and equality of the Unicode classes (1 is the lowest non-zero class).
// Unlisted code points are starters (class 0).
struct CombiningRank {
  uint32_t code_point;
  uint8_t rank;
};

extern const NfkdMapping kNfkdMappings[];
extern const size_t kNfkdMappingCount;
extern const uint32_t kNfkdPool[];
extern const CompositionPair kCompositionPairs[];
extern const size_t kCompositionPairCount;
extern const CombiningRank kCombiningRanks[];
extern const size_t kCombiningRankCount;
extern const char kRedactionRulesSha256[];

}  // namespace fortis::security
